    "explanation": "& explication\n\nLe discriminant majeur entre ces deux stades est l'état du col utérin, associé à la vitalité de la grossesse.\n\nA exacte : dans la menace, le col reste fermé — c'est ce qui autorise l'espoir de poursuite de la grossesse.\n\nB exacte : la dilatation de l'orifice interne signe l'engagement irréversible du processus d'expulsion.\n\nC fausse : la cavité vide caractérise l'avortement complet, pas la menace (où le sac est bien présent).\n\nD exacte : l'activité cardiaque est le critère cardinal de la menace d'avortement.\n\nE fausse : dans l'avortement inévitable, le produit de la grossesse est encore entier dans la cavité utérine ; seule la dilatation cervicale annonce l'expulsion imminente. L'expulsion complète définit l'avortement complet.",
