    "explanation": "La rétention de débris de conception est le lit de l'hémorragie secondaire, de l'endométrite (pouvant évoluer vers l'avortement septique) et des synéchies utérines (syndrome d'Asherman) responsables d'hypoménorrhée et d'infertilité.\n\nB, C, D fausses : ce ne sont pas des complications de l'avortement incomplet, mais des entités pathologiques distinctes.\n\nE fausse : l'affirmation est dangereuse et contredit le cours.",
    "difficulty": "Concours Résidanat",
    "module": "mod-5-gyn",
    "academicYear": "5ème Année"
