    "explanation": "La cinétique des βhCG est l'élément clé : une décroissance anormale ou une stagnation associée à une cavité utérine vide et à des signes cliniques oriente vers la GEU. L'échographie endovaginale de suivi recherche une masse annexielle ou un sac extra-utérin.\n\nA fausse : une valeur isolée est insuffisante ; c'est la cinétique qui est informative.\n\nC fausse : l'ASP n'a aucune place dans cette situation.\n\nD fausse : le FCU est un examen de dépistage du cancer du col, sans rapport.\n\nE fausse : l'hystéroscopie n'est ni indiquée ni réalisable dans ce contexte d'urgence.",
