    "questionText": "[Fièvre et métrorragies fétides après avortement non médicalisé — Avortement septique]\nIdentité Mme F. Z., 22 ans, célibataire, sans suivi médical.\n\nMotif Amenée aux urgences pour fièvre à 39,2 °C avec frissons, douleurs pelviennes intenses et métrorragies fétides, 5 jours après un avortement réalisé dans des conditions non médicalisées.\n\nExamen Altération de l'état général, TA 90/60 mmHg, pouls 118/min, température 39,2 °C, pâleur cutanéo-muqueuse. Abdomen douloureux diffusément, défense absente. Au spéculum : métrorragies malodorantes, leucorrhées purulentes, col ouvert. Au toucher vaginal : utérus augmenté, très sensible, mobilisation douloureuse.\n\nBiologie GB 19 800/mm³, CRP 148 mg/L, Hb 9,2 g/dL.\n\nÉchographie Contenu intracavitaire hétérogène, débris de conception retenus, épanchement pelvien minime.\n\nQuestion : Quel est le diagnostic ?",
